CREATE TABLE eng.mtm_daily (biz_date DATE NOT NULL, kind CHAR(1) NOT NULL, id INT NOT NULL, ref VARCHAR(10) NOT NULL, product_code VARCHAR(8) NOT NULL, cp_id INT NULL, tenor_month CHAR(7) NULL, s INT NOT NULL, qty DECIMAL(12,3) NOT NULL, tau INT NULL, curve_price DECIMAL(19,4) NOT NULL, contract_price DECIMAL(12,2) NOT NULL, fx DECIMAL(12,6) NOT NULL, mtm_myr DECIMAL(19,2) NOT NULL, version_no INT NOT NULL, restated BIT NOT NULL);
CREATE TABLE eng.attribution_trade (biz_date DATE NOT NULL, kind CHAR(1) NOT NULL, id INT NOT NULL, ref VARCHAR(10) NOT NULL, b1 DECIMAL(19,2) NOT NULL, b2 DECIMAL(19,2) NOT NULL, b3 DECIMAL(19,2) NOT NULL, b4 DECIMAL(19,2) NOT NULL, b5 DECIMAL(19,2) NOT NULL, b6 DECIMAL(19,2) NOT NULL, mtm_open DECIMAL(19,2) NOT NULL, mtm_close DECIMAL(19,2) NOT NULL);
CREATE TABLE eng.attribution_daily (biz_date DATE NOT NULL, mtm_open DECIMAL(19,2) NOT NULL, mtm_close DECIMAL(19,2) NOT NULL, d_mtm DECIMAL(19,2) NOT NULL, b1 DECIMAL(19,2) NOT NULL, b2 DECIMAL(19,2) NOT NULL, b3 DECIMAL(19,2) NOT NULL, b4 DECIMAL(19,2) NOT NULL, b5 DECIMAL(19,2) NOT NULL, b6 DECIMAL(19,2) NOT NULL, sum_b DECIMAL(19,2) NOT NULL, realised DECIMAL(19,2) NOT NULL, restated BIT NOT NULL, run_ts DATETIME2(0) NOT NULL);
CREATE TABLE eng.exposure_daily (biz_date DATE NOT NULL, cp_id INT NOT NULL, mtm_net DECIMAL(19,2) NOT NULL, ar_open DECIMAL(19,2) NOT NULL, unbilled DECIMAL(19,2) NOT NULL, delivery_risk DECIMAL(19,2) NOT NULL, collateral DECIMAL(19,2) NOT NULL, exposure DECIMAL(19,2) NOT NULL, limit_myr DECIMAL(18,2) NOT NULL, utilisation DECIMAL(12,4) NOT NULL, band VARCHAR(6) NOT NULL, ecl DECIMAL(19,2) NOT NULL);
CREATE TABLE eng.hedge_test_monthly (month_key CHAR(7) NOT NULL, hedge_rel_id INT NOT NULL, product_code VARCHAR(8) NOT NULL, forecast_month CHAR(7) NOT NULL, cum_dfv_item DECIMAL(19,2) NOT NULL, cum_dfv_instr DECIMAL(19,2) NOT NULL, dollar_offset DECIMAL(12,4) NULL, assessed BIT NOT NULL, prospective_slope DECIMAL(12,4) NOT NULL, prospective_r2 DECIMAL(12,4) NOT NULL, effective BIT NOT NULL, ineffectiveness_pl DECIMAL(19,2) NOT NULL, oci_open DECIMAL(19,2) NOT NULL, oci_effective_added DECIMAL(19,2) NOT NULL, oci_reclassified DECIMAL(19,2) NOT NULL, oci_close DECIMAL(19,2) NOT NULL);
CREATE TABLE eng.control_total (control_name VARCHAR(60) NOT NULL, biz_date DATE NULL, dim_key VARCHAR(30) NULL, value_num DECIMAL(19,4) NULL, value_txt VARCHAR(200) NULL, basis VARCHAR(400) NOT NULL, frozen_at DATETIME2(0) NOT NULL);
CREATE TABLE eng.run_log (biz_date DATE NOT NULL, as_of_date DATE NOT NULL, restated BIT NOT NULL, run_ts DATETIME2(0) NOT NULL, n_positions INT NOT NULL, mtm_close DECIMAL(19,2) NOT NULL, unexplained DECIMAL(19,2) NOT NULL);
CREATE TABLE eng.w_pos (kind CHAR(1) NOT NULL, id INT NOT NULL, ref VARCHAR(10) NOT NULL, product_code VARCHAR(8) NOT NULL, cp_id INT NULL, tenor_month CHAR(7) NULL, s INT NOT NULL, qty DECIMAL(12,3) NOT NULL, k DECIMAL(12,2) NOT NULL, k_conf DECIMAL(12,2) NOT NULL, fx DECIMAL(12,6) NOT NULL, tau INT NULL, version_no INT NOT NULL, curve_price DECIMAL(19,4) NULL, mtm_myr DECIMAL(19,2) NULL);
CREATE TABLE eng.w_pt (product_code VARCHAR(8) NOT NULL, curve_date DATE NOT NULL, t INT NOT NULL, price DECIMAL(12,2) NOT NULL);
CREATE TABLE eng.w_req (req_kind CHAR(1) NOT NULL, kind CHAR(1) NOT NULL, id INT NOT NULL, product_code VARCHAR(8) NOT NULL, curve_date DATE NOT NULL, tau INT NOT NULL, t0 INT NULL, t1 INT NULL, price DECIMAL(19,4) NULL);
